  ('jetti', 'Jetti', '', '', '', '', 'Jetti', '[{"kategorie": "", "text": "Marietta (weiblicher Vorname)"}]'::jsonb, ''),
  ('friara', 'friara', '', '', '', 'Grundwortschatz Wienerisch', 'früher', '[{"kategorie": "wörtlich", "text": "\"früher\" (Komparativ von \"früh\", vom mittelhochdeutschen \"vrüe\"=\"früh\")"}, {"kategorie": "allg.", "text": "\"zeitlich vorher\", \"vormals\", \"einst\""}]'::jsonb, ''),
  ('jetza', 'jetza', '', '', '', 'Grundwortschatz Wienerisch', 'jetza', '[{"kategorie": "wörtlich", "text": "\"jetzt\" (vom mittelhochdeutschen \"ieze\"=\"jetzt\")"}, {"kategorie": "allg.", "text": "nun, im Moment, nunmehr, \"jetzo\""}]'::jsonb, ''),
  ('jetzad', 'jetzad', '', '', '', '', 'jetzad', '[{"kategorie": "wörtlich", "text": "\"jetzt\" (vom mittelhochdeutschen \"izit\"=\"jetzt\")"}, {"kategorie": "", "text": "nun, im Moment, numehr, \"jetzo\""}]'::jsonb, ''),
  ('jetzn', 'jetzn', '', '', '', '', 'jetzen', '[{"kategorie": "wörtlich", "text": "\"jetzt\" (vom mittelhochdeutschen \"ieze\"=\"jetzt\")"}, {"kategorie": "", "text": "nun, im Moment, numehr, \"jetzo\""}]'::jsonb, ''),
  ('dschimihoosn', 'Dschimihoosn', '', '', '', '', 'Jimmy-Hosen', '[{"kategorie": "wörtlich", "text": "\"Jimmy-Hose\" (Verballhornung von \"Blue Jeans\")"}, {"kategorie": "", "text": "Jeanshose, Jeansstoffhose, \"Denimhose\", \"Blue Jeans\"-Hose"}]'::jsonb, ''),
  ('jodl', 'Jodl', '', '', '', '', 'Jodel', '[{"kategorie": "wörtlich, Koseform für", "text": "\"Jodok\" bzw. \"Jodokus\""}, {"kategorie": "", "text": "Stier, auch Stierhalter"}, {"kategorie": "fig.", "text": "einfältiger Mensch, [[Depp]], [[Doodl]], [[Dillo]]"}]'::jsonb, 'Da Jodl is löödich!'),
  ('jodlhuat', 'Jodlhuat', '', '', '', '', 'Jodlhut', '[{"kategorie": "wörtlich", "text": "\"Stierhut\" (von [[Jodl]]=\"Stier\")"}, {"kategorie": "", "text": "Spitzer Filzhut mit breiter, meist nach oben gebogener Krempe (22cm hoch, aus dunklem Wollfilz gearbeitet, wurde seit dem 16. Jahrhundert gerne von Angehörigen der unteren Bevölkerungsschichten getragen)"}, {"kategorie": "hist.", "text": "kennzeichnendes Merkmal der aufständischen Bauern (politisches Symbol, Anfang 17. Jahrhundert)"}]'::jsonb, ''),
  ('jogl', 'Jogl', '', '', '', '', 'Jogel', '[{"kategorie": "wörtlich, Koseform für", "text": "\"Jakob\" (männlicher Vorname)"}, {"kategorie": "fig.", "text": "Bauerntölpel, Hinterwäldler, Provinzler, Landei"}, {"kategorie": "", "text": "[[Surm]], [[Stoffl]], [[Staudenhocker]], [[Baamschabl]], [[Landla]]"}]'::jsonb, ''),
  ('joghuadbecha', 'Joghuadbecha', '', '', '', '', 'Joghurtbecher', '[{"kategorie": "wörtlich", "text": "\"Kunststoffbehälter für Joghurt\" (Determinativkompositum aus \"Joghurt\"=\"Milchprodukt\" und \"Becher\")"}, {"kategorie": "scherzhaft für", "text": "vollverkleidetes Sportmotorrad mit Straßenzulassung (in Anspielung darauf, dass die Vollverkleidung den maßgeblichen „Inhalt“ des Motorrades – das heißt Motor, Rahmen usw. [d.h. alles, was sonst stolz zur Schau gestellt wird] umschließt und damit unsichtbar macht – wie der besagte Becher seinen Inhalt \"Joghurt\", was Motorradfreaks seinerzeit [80-er Jahre] sauer aufstoßen ließ)."}]'::jsonb, ''),
  ('joisl', 'Joisl', '', '', '', '', 'Joisl', '[{"kategorie": "wörtlich, Koseform für", "text": "\"Josel\" (=Kurzform des männlichen Vornamens \"Jossele\", jiddische Variante für \"Josef\")"}, {"kategorie": "fig.", "text": "Tölpel, [[Dillo]], [[Dolm]]"}]'::jsonb, ''),
  ('dscholli', 'Dscholli', '', '', '', '', 'Jolly', '[{"kategorie": "wörtlich, Kartenspielerjargon", "text": "\"Jolly Joker\" (Spielkarte mit dem Bild eines Hofnarren [\"Jolly\"], die besonders wertvoll ist, da sie alle anderen Karten ersetzen kann\", vom englischen \"jolly\"=\"fröhlich\" bzw. \"vergnügt\" sowie \"joker\"=\"Spaßmacher\")"}, {"kategorie": "fig., scherzhaft für", "text": "kleiner Rausch, Räuschlein, [[Schwipserl]], [[Spitzerl]], [[Kapuzerl]], [[Schwalberl]], [[Dulliäh]]"}, {"kategorie": "Fußballerjargon", "text": "\"rote Karte\", \"Freikarte für die Kabine\""}]'::jsonb, ''),
  ('jonasgrottn', 'Jonasgrottn', '', '', '', '', 'Jonasgrotten', '[{"kategorie": "wörtlich", "text": "\"Jonasgrotte\" (\"die Grotte von Bürgermeister Franz Jonas\" [1899-1974])"}, {"kategorie": "scherzhaft für", "text": "Fußgängerpassage unter der Wiener Opernkreuzung (errichtet in der Amtszeit des damals regierenden Bürgermeisters [[Franz]] Jonas)"}]'::jsonb, ''),
  ('jonasreindl', 'Jonasreindl', '', '', '', '', 'Jonasreindl', '[{"kategorie": "wörtlich", "text": "\"Jonasreindel\" (\"die Bratpfanne von Bürgermeister [[Franz]] Jonas\" [1899-1974])"}, {"kategorie": "scherzhaft für", "text": "unterirdische Fußgängerpassage und Straßenbahnschleife unter dem Wiener [[Schottentor]] (errichtet in der Amtszeit des damals regierenden Bürgermeisters Franz Jonas)"}]'::jsonb, ''),
  ('schottntoa', 'Schottntoa', '', '', '', '', 'Schottentor', '[{"kategorie": "wörtlich, hist.", "text": "\"Porta Scotorum\" (\"Tor der Schotten\", ehemaliges turmbewehrtes Tor in der Wiener Stadtmauer, das 1860 abgetragen wurde)"}, {"kategorie": "heute", "text": "Bezeichnung für die Kreuzung der Ringstraße mit der [[Schottengasse]]  (auch Name der U2-Station), benannt nach dem dort gelegenen [[Schottenstift]]"}]'::jsonb, ''),
  ('buagtoa', 'Buagtoa', '', '', '', '', 'Burgtor', '[{"kategorie": "wörtlich, hist.", "text": "\"mehrteilige Toranlage der Hofburg, die vom [[Burgplatz]] auf das [[Glacis]] führte\""}, {"kategorie": "allg.", "text": "Toranlage im Areal der [[Hofburg]], zwischen [[Heldenplatz]] und [[Burgring]]"}]'::jsonb, ''),
  ('buagring', 'Buagring', '', '', '', '', 'Burgring', '[{"kategorie": "wörtlich", "text": "\"Burgring\" (Determinativkompositum aus \"Burg\"=[[Hofburg]] und \"Ring\"=[[Wiener Ringstraße]])"}, {"kategorie": "", "text": "Teil der Wiener Ringstraße (liegt im westlichen Abschnitt der [[Ringstraße]] und verbindet den [[Dr]].-Karl-Renner-Ring [beim Parlament] mit dem [[Opernring]] [beim Wiener Opernhaus]. Der Burgring entstand im Rahmen der großangelegten Stadtentwicklungsprojekte im 19. Jahrhundert, insbesondere während der 1860er Jahre, als die mittelalterlichen Stadtmauern Wiens abgerissen wurden, um Platz für die moderne Ringstraße zu schaffen)"}]'::jsonb, ''),
  ('opanring', 'Opanring', '', '', '', '', 'Opernring', '[{"kategorie": "hist.", "text": "\"prominenter Abschnitt der [[Wiener]] Ringstraße im 1. Bezirk ([[Innere]] Stadt), der nach der [[Wiener]] Staatsoper benannt ist\""}, {"kategorie": "", "text": "Mit der Wiener Staatsoper, dem [[Hotel]] Sacher, der [[Akademie]] der bildenden Künste Wien und dem [[Ringstraßenpalais]] ist der Opernring ein zentraler Ort des kulturellen Lebens und ein bedeutendes Wahrzeichen der Stadt"}]'::jsonb, ''),
  ('philharmonikaschrdossn', 'Philharmonikaschrdossn', '', '', '', '', 'Philharmonikerstraße', '[{"kategorie": "hist.", "text": "zentrale Straße im 1. Wiener Gemeindebezirk ([[Innere]] Stadt)"}, {"kategorie": "", "text": "Sie verläuft parallel zur [[Wiener]] Ringstraße und liegt in unmittelbarer Nähe einiger der bekanntesten Sehenswürdigkeiten Wiens, darunter die [[Wiener]] Staatsoper und das [[Hotel]] Sacher"}, {"kategorie": "", "text": "Die Straße erhielt ihren Namen im Jahr 1870 in Anerkennung des Wiener Philharmoniker-Orchesters, das zu den führenden Orchestern der Welt gehört und seit dem 19. Jahrhundert maßgeblich zur musikalischen Kultur Wiens beiträgt"}]'::jsonb, ''),
  ('schdubnring', 'Schdubnring', '', '', '', '', 'Stubenring', '[{"kategorie": "wörtlich", "text": "\"Stubenring\" (Abschnitt der berühmten [[Wiener]] Ringstraße, welche die [[Innere]] Stadt (den 1. Wiener Gemeindebezirk) umschließt)"}, {"kategorie": "allg.", "text": "östlichster Teil der [[Ringstraße]] (verläuft zwischen dem [[Schottenring]] und dem [[Franz-Josefs-Kai]];  der Name \"Stubenring\" leitet sich von dem ehemaligen Stadttor [[Stubentor]] ab, das Teil der mittelalterlichen Stadtbefestigung Wiens war)"}]'::jsonb, ''),
  ('justizpalast', 'Justizpalast', '', '', '', '', 'Justizpalast', '[{"kategorie": "hist.", "text": "monumentales Gebäude im 1. Wiener Gemeindebezirk ([[Innere]] Stadt)"}, {"kategorie": "", "text": "Der Justizpalast ist ein bedeutendes Beispiel für die Architektur des Historismus und ein zentraler Ort der österreichischen Justiz, der die höchsten Gerichte Österreichs beherbergt, darunter den Obersten Gerichtshof, den Obersten Gerichtshof für Zivil- und Strafsachen sowie das Oberlandesgericht Wien"}, {"kategorie": "", "text": "Der Justizpalast wurde zwischen 1875 und 1881 im Stil der Neorenaissance erbaut, was typisch für den [[Historismus]] des späten 19. Jahrhunderts ist. Der Stil greift Elemente der italienischen Renaissance auf und kombiniert sie mit barocken Einflüssen, um dem Gebäude eine repräsentative und majestätische Wirkung zu verleihen"}, {"kategorie": "", "text": "Im Inneren des Justizpalastes befindet sich die berühmte Große Halle, die für ihre prachtvolle Ausstattung bekannt ist. Die Halle ist mit Marmor, Fresken und Skulpturen geschmückt und verfügt über ein kunstvolles Glasdach, das Tageslicht einlässt und der Halle eine helle, erhabene Atmosphäre verleiht"}, {"kategorie": "", "text": "Der Justizpalast ist besonders bekannt für den Justizpalastbrand am 15. Juli 1927. Dieser Vorfall wurde durch einen umstrittenen Gerichtsentscheid ausgelöst, der zu heftigen politischen Protesten und Unruhen führte. Die Demonstrationen eskalierten und führten schließlich zur Brandstiftung am Justizpalast, bei der das Gebäude schwer beschädigt wurde. Der Brand gilt als ein symbolischer Moment in der Geschichte der Ersten Republik Österreichs und hatte weitreichende politische Konsequenzen."}]'::jsonb, ''),
  ('akademiiteata', 'Akademiiteata', '', '', '', '', 'Akademietheater', '[{"kategorie": "hist.", "text": "\"eines der renommiertesten Sprechtheater in Wien und ein bedeutender Teil der Wiener Bühnenlandschaft\""}, {"kategorie": "", "text": "Es ist die zweite Spielstätte des Wiener [[Burgtheaters]] und befindet sich im 3. Wiener Gemeindebezirk ([[Landstraße]]), an der Lisztstraße in der Nähe des [[Stadtparks]]"}, {"kategorie": "", "text": "Das Akademietheater wurde 1911 eröffnet und sollte ursprünglich als Spielstätte für experimentelle und moderne Stücke dienen, die neben dem klassischen Repertoire des Burgtheaters aufgeführt werden konnten. Es wurde von den Architekten Ludwig Baumann und Fellner & Helmer entworfen, die für zahlreiche Theaterbauten in Europa bekannt waren"}, {"kategorie": "", "text": "Als zweite Bühne des [[Wiener]] Burgtheaters genießt das Akademietheater den gleichen hohen künstlerischen Ruf. Es ist bekannt für seine anspruchsvollen und oft innovativen Inszenierungen, die sowohl klassische als auch zeitgenössische Dramatik umfassen"}, {"kategorie": "", "text": "Der Theatersaal des Akademietheaters ist im Jugendstil gehalten und zeichnet sich durch seine intime Atmosphäre aus. Mit einer Kapazität von etwa 500 Plätzen ist das Akademietheater kleiner und persönlicher als das große Haus des Burgtheaters, was es besonders geeignet für intensivere und experimentellere Inszenierungen macht."}]'::jsonb, ''),
  ('votivkiachn', 'Votivkiachn', '', '', '', '', 'Votivkirche', '[{"kategorie": "hist.", "text": "\"bedeutende neugotische Kirche im 9. Wiener Gemeindebezirk\" ([[Alsergrund]])"}, {"kategorie": "", "text": "Die Votivkirche befindet sich am Rooseveltplatz, in der Nähe der [[Universität]] Wien und des [[Sigmund-Freud-Parks]]. Sie ist ein markantes Beispiel der Neugotik und eine bedeutende Sehenswürdigkeit der Stadt Wien"}, {"kategorie": "", "text": "Die Votivkirche wurde als Dank für das Überleben von Kaiser [[Franz]] Joseph I. nach einem Attentatsversuch am 18. Februar 1853 errichtet. Sein Bruder, [[Erzherzog]] Ferdinand Maximilian, initiierte den Bau der Kirche, der als „Votivgabe“ für die Rettung des Kaisers angesehen wurde. Der Grundstein wurde am 24. April 1856 gelegt, und die Kirche wurde nach einer Bauzeit von mehr als zwei Jahrzehnten im Jahr 1879, zum 25. Thronjubiläum des Kaisers, geweiht. Der Entwurf der Votivkirche stammt von Heinrich von Ferstel, einem der prominentesten Architekten des [[Historismus]]"}]'::jsonb, ''),
  ('konzeathaus', 'Konzeathaus', '', '', '', '', 'Konzerthaus', '[{"kategorie": "hist.", "text": "\"eines der bedeutendsten Konzerthäuser in Wien\""}, {"kategorie": "", "text": "Es befindet sich im 3. Wiener Gemeindebezirk ([[Landstraße]]), in der Nähe des [[Stadtparks]], und ist für sein vielfältiges musikalisches Programm und seine hervorragende Akustik bekannt"}, {"kategorie": "", "text": "Das Wiener Konzerthaus wurde zwischen 1911 und 1913 erbaut und am 19. Oktober 1913 eröffnet. Die Eröffnung fand mit einem Festkonzert statt, bei dem unter anderem Richard Strauss’ „Festliches Präludium“ uraufgeführt wurde"}, {"kategorie": "", "text": "Das Wiener Konzerthaus ist ein architektonisches Meisterwerk, das Elemente des Jugendstils mit neoklassizistischen Stilelementen kombiniert. Das Gebäude ist außen wie innen reich verziert und spiegelt die künstlerische Aufbruchsstimmung zu Beginn des 20. Jahrhunderts wider"}, {"kategorie": "", "text": "Der \"Große Saal\" des Wiener Konzerthauses ist der größte der vier Säle und bietet Platz für rund 1.840 Zuhörer. Weitere Säle sind der \"Mozart-Saal\", der \"Schubert-Saal\" und der \"Berio-Saal\", die jeweils für bestimmte musikalische Genres und Aufführungen konzipiert sind."}]'::jsonb, ''),
  ('kuenstlahaus', 'Künstlahaus', '', '', '', '', 'Künstlerhaus', '[{"kategorie": "", "text": "Es befindet sich am [[Karlsplatz]] im 1. Wiener Gemeindebezirk ([[Innere]] Stadt) und gehört zu den ältesten Ausstellungshäusern für zeitgenössische Kunst in Wien"}, {"kategorie": "", "text": "Das Künstlerhaus Wien wurde 1868 von der Künstlervereinigung „Genossenschaft der bildenden Künstler Wiens“ gegründet, die auch heute noch das Gebäude betreibt. Die Genossenschaft war eine der wichtigsten Künstlervereinigungen in Österreich und spielte eine zentrale Rolle im kulturellen Leben Wiens des 19. Jahrhunderts"}, {"kategorie": "", "text": "Das Künstlerhaus ist im Stil des [[Historismus]] erbaut, einer architektonischen Epoche, die sich durch die Wiederaufnahme und Kombination verschiedener historischer Stilelemente auszeichnet. Das Gebäude hat eine repräsentative Fassade mit klassischen Säulen und dekorativen Elementen, die das Gebäude zu einem markanten Bestandteil des [[Karlsplatzes]] machen"}, {"kategorie": "", "text": "Ein Teil des Gebäudes beherbergt das Künstlerhaus Kino, ein traditionsreiches Kino, das sich auf die Präsentation von Independent- und Arthouse-Filmen spezialisiert hat. Das Kino ist ein wichtiger Bestandteil der Wiener Filmszene und zieht ein kunstinteressiertes Publikum an"}]'::jsonb, ''),
  ('koarlsplotz', 'Koarlsplotz', '', '', '', '', 'Karlsplatz', '[{"kategorie": "hist.", "text": "\"einer der bedeutendsten und geschichtsträchtigsten Plätze der Stadt (gelegen im 1. und 4. Wiener Gemeindebezirk, der [[Inneren]] Stadt und [[Wieden]])\""}, {"kategorie": "", "text": "Er entstand im Zuge der [[Wienflussregulierung]] zwischen 1894 und 1900 und wurde 1899 nach [[Kaiser]] Karl VI. benannt. Die Regulierung ermöglichte die Einwölbung des Wienflusses, wodurch ein langgestreckter Platz entstand"}, {"kategorie": "", "text": "Kaiser Karl VI. hatte im Zuge der Pestepidemie von 1713/14 das Gelübde abgelegt, eine Kirche zu errichten – die [[Karlskirche]], die von 1716 bis 1737 erbaut wurde und den Platz prägt"}, {"kategorie": "", "text": "Vor der Entstehung des Platzes befand sich dort die Elisabethbrücke, benannt nach der Frau von Kaiser Franz Joseph I. Diese Brücke wurde jedoch 1897 abgerissen, um Platz für die Neugestaltung zu machen"}, {"kategorie": "", "text": "Der Karlsplatz ist auch von wichtigen Bauwerken umgeben, wie der [[Karlskirche]], dem [[Künstlerhaus]], der [[Technischen]] Universität Wien und dem [[Wien]] Museum. Besonders der [[Resselpark]], benannt nach dem Erfinder Josef Ressel (dem Erfinder des Schiffspropellers), dominiert den südlichen Teil des Platzes"}, {"kategorie": "", "text": "Am Park befinden sich auch zahlreiche Denkmäler, darunter Statuen von Johannes Brahms und Josef Madersperger."}]'::jsonb, ''),
  ('koarlskiachn', 'Koarlskiachn', '', '', '', '', 'Karlskirche', '[{"kategorie": "hist.", "text": "\"eine der bedeutendsten Barockkirchen Wiens und ein herausragendes architektonisches Wahrzeichen der Stadt Wien\" (offiziell \"Römisch-katholische Pfarrkirche St. Karl Borromäus\")"}, {"kategorie": "", "text": "Sie befindet sich am [[Karlsplatz]] im 4. Wiener Gemeindebezirk ([[Wieden]]) und dominiert das Erscheinungsbild dieses zentralen Platzes von Wien"}, {"kategorie": "", "text": "Die Karlskirche wurde von [[Kaiser]] Karl VI. in Auftrag gegeben, der nach dem Ende einer Pestepidemie im Jahr 1713 gelobte, eine Kirche zu Ehren seines Namenspatrons, des heiligen Karl Borromäus, zu errichten. Karl Borromäus war ein bedeutender Kirchenreformer und Kardinal von Mailand, der als Schutzheiliger gegen die Pest verehrt wurde"}, {"kategorie": "", "text": "Der Bau der Karlskirche begann 1716 unter der Leitung des berühmten Barockarchitekten Johann Bernhard Fischer von Erlach, der den Entwurf der Kirche gestaltete. Nach seinem Tod 1723 wurde der Bau von seinem Sohn Joseph Emanuel Fischer von Erlach fortgeführt. Die Kirche wurde 1737 fertiggestellt"}, {"kategorie": "", "text": "Die Karlskirche ist ein Meisterwerk des Hochbarock und kombiniert verschiedene architektonische Stilelemente, die von der Antike inspiriert sind. Die Fassade ist von der römischen Architektur beeinflusst, während die Kuppel und die hohen Säulen an byzantinische und barocke Vorbilder erinnern"}, {"kategorie": "", "text": "Die monumentale Kuppel der Karlskirche ist ein zentrales Element des Bauwerks und dominiert das Stadtbild. Sie hat einen Durchmesser von etwa 25 Metern und erreicht eine Höhe von 72 Metern. Die Kuppel ist reich mit Fresken verziert, die Szenen aus dem Leben des heiligen Karl Borromäus darstellen und von Johann Michael Rottmayr geschaffen wurden."}]'::jsonb, ''),
  ('musikverein', 'Musikverein', '', '', '', '', 'Musikverein', '[{"kategorie": "hist.", "text": "\"Der Musikverein in Wien\" (offiziell bekannt als \"Gesellschaft der Musikfreunde in Wien\"), ist eines der berühmtesten Konzerthäuser der Welt und eine zentrale Institution im musikalischen Leben Wiens"}, {"kategorie": "", "text": "Das Gebäude befindet sich im 1. Wiener Gemeindebezirk ([[Innere]] Stadt), am Musikvereinsplatz nahe dem [[Karlsplatz]], und ist insbesondere für seinen prächtigen [[Goldenen]] Saal bekannt, der als einer der besten Konzertsäle der Welt gilt"}, {"kategorie": "", "text": "Der Musikverein ist im Stil des Neoklassizismus erbaut und zeichnet sich durch seine prächtige Fassade und die beeindruckende Innenarchitektur aus. Der Bau orientiert sich an antiken Tempelbauten und ist reich mit Säulen, Statuen und Ornamenten verziert"}, {"kategorie": "", "text": "Der Bau des Musikvereinsgebäudes begann im Jahr 1867 und wurde 1870 abgeschlossen. Es wurde nach den Plänen des dänischen Architekten Theophil von Hansen errichtet, der auch andere bedeutende Gebäude in Wien, wie das [[Parlamentsgebäude]], entworfen hat."}]'::jsonb, ''),
  ('johannesgossn', 'Johannesgossn', '', '', '', '', 'Johannesgasse', '[{"kategorie": "hist.", "text": "bedeutende Straße im 1. Wiener Gemeindebezirk ([[Innere]] Stadt)"}, {"kategorie": "", "text": "Sie  erstreckt sich von der [[Kärntner]] Straße bis zum [[Stadtpark]] und ist bekannt für ihre historische Architektur und ihre kulturellen Institutionen"}, {"kategorie": "", "text": "Ein zentraler Punkt in der Johannesgasse ist die [[Musik und Kunst Privatuniversität der Stadt Wien (MUK)]], die sich an der Adresse Johannesgasse 4a befindet. Diese Institution, ehemals bekannt als [[Konservatorium Wien]], ist eine der bedeutendsten Musik- und Kunsthochschulen in Wien."}]'::jsonb, ''),
  ('himmaepfoatgossn', 'Himmäpfoatgossn', '', '', '', '', 'Himmelpfortgasse', '[{"kategorie": "hist.", "text": "\"historische Straße im 1. Wiener Gemeindebezirk\" ([[Innere]] Stadt)"}, {"kategorie": "", "text": "Sie liegt in einem der ältesten Teile Wiens und verläuft von der [[Kärntner]] Straße bis zur [[Johannesgasse]]. Die Gasse ist bekannt für ihre bedeutenden historischen Gebäude, darunter einige prächtige Palais, die von Adeligen und wohlhabenden Bürgern bewohnt wurden"}]'::jsonb, ''),
  ('annagossn', 'Annagossn', '', '', '', '', 'Annagasse', '[{"kategorie": "hist.", "text": "malerische und historische Gasse im 1. Wiener Gemeindebezirk ([[Innern]] Stadt)"}, {"kategorie": "", "text": "Sie mündet als Quergasse in die [[Kärntner]] Straße, eine der bekanntesten Einkaufsstraßen Wiens, und ist bekannt für ihren charmanten, fast dörflichen Charakter inmitten der belebten Innenstadt"}, {"kategorie": "", "text": "Die Annagasse erhielt ihren Namen von der St.-Anna-Kirche, die im 16. Jahrhundert errichtet wurde und eines der bedeutendsten Bauwerke in dieser Gasse ist. Die Kirche ist nach der heiligen Anna, der Mutter Marias, benannt ist ein schönes Beispiel für barocke Kirchenarchitektur in Wien"}]'::jsonb, ''),
  ('woifischgossn', 'Woifischgossn', '', '', '', '', 'Walfischgasse', '[{"kategorie": "hist.", "text": "kurze, aber historisch bedeutsame Straße im 1. Wiener Gemeindebezirk ([[Innere]] Stadt)"}, {"kategorie": "", "text": "Die Walfischgasse liegt in unmittelbarer Nähe zur [[Wiener]] Staatsoper und wurde im Jahr 1862 nach einem Gasthaus mit dem Namen \"Zum weißen Walfisch\" benannt, das sich in der Nähe befunden hat"}, {"kategorie": "", "text": "Entlang der Walfischgasse finden sich mehrere gut erhaltene Gebäude aus dem 19. und frühen 20. Jahrhundert, die den typischen Wiener Charme ausstrahlen. Diese Gebäude sind oft reich verziert und repräsentieren die Architektur der Ringstraßenzeit."}]'::jsonb, ''),
  ('mahlerschdrossn', 'Mahlerschdrossn', '', '', '', '', 'Mahlerstraße', '[{"kategorie": "hist.", "text": "\"zentrale und historische Straße im 1. Wiener Gemeindebezirk\" ([[Innere]] Stadt)"}, {"kategorie": "", "text": "Sie verläuft parallel zur [[Ringstraße]] und befindet sich in unmittelbarer Nähe zur Wiener Staatsoper"}, {"kategorie": "", "text": "Die Mahlerstraße erhielt ihren Namen 1919, acht Jahre nach dem Tod Gustav Mahlers, um dessen bedeutende Beiträge zur Musik zu ehren. Mahler gilt als einer der wichtigsten Vertreter der spätromantischen Musik und hatte einen starken Einfluss auf die Entwicklung der Musik im 20. Jahrhundert"}, {"kategorie": "", "text": "Entlang der Mahlerstraße finden sich mehrere repräsentative Gebäude aus der Gründerzeit, die den typischen architektonischen Stil der Ringstraßenära widerspiegeln. Diese Bauten sind oft reich verziert und tragen zum eleganten Erscheinungsbild der Straße bei."}]'::jsonb, ''),
  ('kapuzinakiachn', 'Kapuzinakiachn', '', '', '', '', 'Kapuzinerkirche', '[{"kategorie": "hist.", "text": "\"bedeutende Kirche am [[Neuen]] Markt im 1. Wiener Gemeindebezirk ([[Innere]] Stadt), offiziell \"Kirche zur Heiligen Maria von den Engeln\""}, {"kategorie": "", "text": "Die Kapuzinerkirche wurde im Jahr 1622 im Auftrag von Kaiserin Anna von Tirol, der Gemahlin von Kaiser Matthias, gegründet. Die Kirche und das angrenzende Kloster wurden von den Kapuzinermönchen geführt, einem Bettelorden, der für seine Bescheidenheit und Einfachheit bekannt ist"}, {"kategorie": "", "text": "Die Kirche wurde im Barockstil erbaut, jedoch in schlichter und einfacher Form, wie es dem Ordenscharakter der Kapuziner entspricht. Sie wurde 1632 geweiht und steht seitdem als Zentrum der Kapuzinergemeinde in Wien:  4. Die wichtigste Besonderheit der Kapuzinerkirche ist die [[Kaisergruft]], die sich unterhalb der Kirche befindet. Diese Gruft ist die letzte Ruhestätte von fast 150 Mitgliedern der Habsburgerfamilie, darunter Kaiser, Könige und deren Angehörige."}]'::jsonb, ''),
  ('kapuzinagruft', 'Kapuzinagruft', '', '', '', '', 'Kapuzinergruft', '[{"kategorie": "", "text": "Sie befindet sich unter der [[Kapuzinerkirche]] am [[Neuen]] Markt im 1. Wiener Gemeindebezirk ([[Innere]] Stadt) und dient als letzte Ruhestätte der Habsburgerdynastie"}, {"kategorie": "", "text": "Kaiser [[Matthias]] ordnete im Zusammenhang mit der Stiftung der Kapuzinerkirche durch seine Frau Anna den Bau einer Gruft an, die ab 1622 von [[Ferdinand]] II. errichtet und später mehrfach erweitert wurde. Die Kapelle wurde 1632 Maria Himmelfahrt geweiht, und 1633 wurden die Leichname von Kaiser Matthias und Kaiserin Anna als erste von ihrem ursprünglichen Begräbnisort in die Gruft überführt"}, {"kategorie": "", "text": "1748 wurde eine zusätzliche Gruft für das Haus Habsburg-Lothringen gebaut. Unter Joseph II. wurde 1787 der Zugang von der Kirche zur Gruft verschlossen, jedoch so, dass er im Todesfall leicht geöffnet werden konnte. Ab [[Leopold]] II. blieben die Zugänge wieder offen"}, {"kategorie": "", "text": "[[Napoleon]] besuchte die Kapuzinergruft 1809 bei Fackelschein. Bei Erweiterungsarbeiten 1824 entdeckte man, dass die Gruft auf einer altrömischen Begräbnisstätte steht. 1845 wurde Gasbeleuchtung installiert, 1909 folgte elektrisches Licht, und der Zugang vom Kloster wurde mit weißen Kacheln versehen"}, {"kategorie": "", "text": "In der Kapuzinergruft sind fast 150 Mitglieder der Habsburgerfamilie beigesetzt, darunter Kaiser [[Franz]] Joseph I. (1830-1916), Kaiserin [[Maria]] Theresia (1717–1780) und Kaiser [[Ferdinand]] I. (1793–1875), letzter Kaiser des Heiligen Römischen Reiches"}, {"kategorie": "", "text": "Die Gruft enthält eine Vielzahl von reich verzierten Sarkophagen, die vom Barock bis zur Moderne reichen und die Macht und den Reichtum der Habsburgerfamilie symbolisieren."}]'::jsonb, ''),
  ('sisi', 'Sisi', '', '', '', '', 'Sissi', '[{"kategorie": "wörtlich, Koseform für", "text": "\"Elisabeth\" (weiblicher Vorname)"}, {"kategorie": "hist.", "text": "liebevoller Kosename für Kaiserin Elisabeth von Österreich, die als eine der bekanntesten und beliebtesten Figuren der Habsburger Monarchie gilt"}, {"kategorie": "", "text": "Elisabeth, geboren am 24. Dezember 1837 als Herzogin in Bayern, heiratete 1854 den österreichischen Kaiser [[Franz]] Joseph I. und wurde damit Kaiserin von Österreich und später Königin von Ungarn"}, {"kategorie": "", "text": "Sisi wurde nach ihrem Tod zu einer fast mythischen Figur, und ihr Leben inspirierte zahlreiche Filme, Bücher und Theaterstücke. Besonders berühmt ist die \"Sissi\"-Filmtrilogie der 1950er Jahre mit Romy Schneider in der Hauptrolle, die ihr Bild in der Popkultur festigte. Bis heute wird sie als Symbol für Freiheit, Schönheit und Tragik wahrgenommen, und ihre Person fasziniert weiterhin Menschen auf der ganzen Welt."}]'::jsonb, ''),
  ('donnabrunnan', 'Donnabrunnan', '', '', '', '', 'Donnerbrunnen', '[{"kategorie": "hist.", "text": "berühmter barocker Brunnen auf dem [[Neuen]] Markt im 1. Wiener Gemeindebezirk ([[Innere]] Stadt), auch bekannt als [[Providentiabrunnen]]"}, {"kategorie": "", "text": "Er wurde von dem bedeutenden österreichischen Bildhauer Georg Raphael Donner geschaffen und zählt zu den herausragendsten Kunstwerken des Wiener Barocks"}, {"kategorie": "", "text": "Der Donnerbrunnen wurde zwischen 1737 und 1739 auf Anordnung von [[Kaiser]] Karl VI. errichtet. Im Zentrum des Donnerbrunnens steht die allegorische Figur der Providentia, die die göttliche Vorsehung symbolisiert. Sie wird von einer majestätischen Säule erhoben und blickt auf das Wasserbecken herab, was ihre Rolle als Hüterin der Wasserquelle und Beschützerin des Volkes unterstreicht"}, {"kategorie": "", "text": "Um die Providentia herum sind vier Flussgötter angeordnet, die die wichtigsten Flüsse des Habsburgerreichs darstellen: die Donau, die Enns, die March und die Traun. Diese Figuren sind in dynamischen Posen dargestellt und symbolisieren die Fruchtbarkeit und Lebensspendende Kraft der Flüsse."}]'::jsonb, ''),
  ('providentiabrunnan', 'Providentiabrunnan', '', '', '', '', 'Providentiabrunnen', '[{"kategorie": "hist.", "text": "berühmter barocker Brunnen auf dem [[Neuen]] Markt im 1. Wiener Gemeindebezirk ([[Innere]] Stadt), auch bekannt als [[Donnerbrunnen]]"}, {"kategorie": "", "text": "Er wurde von dem bedeutenden österreichischen Bildhauer Georg Raphael Donner geschaffen und zählt zu den herausragendsten Kunstwerken des Wiener Barocks"}, {"kategorie": "", "text": "Der Providentiabrunnen wurde zwischen 1737 und 1739 auf Anordnung von [[Kaiser]] Karl VI. errichtet. Im Zentrum des Donnerbrunnens steht die allegorische Figur der Providentia, die die göttliche Vorsehung symbolisiert. Sie wird von einer majestätischen Säule erhoben und blickt auf das Wasserbecken herab, was ihre Rolle als Hüterin der Wasserquelle und Beschützerin des Volkes unterstreicht"}, {"kategorie": "", "text": "Um die Providentia herum sind vier Flussgötter angeordnet, die die wichtigsten Flüsse des Habsburgerreichs darstellen: die Donau, die Enns, die March und die Traun. Diese Figuren sind in dynamischen Posen dargestellt und symbolisieren die Fruchtbarkeit und Lebensspendende Kraft der Flüsse."}]'::jsonb, ''),
  ('vamoeoelungsbrunnan', 'Vamöölungsbrunnan', '', '', '', '', 'Vermählungsbrunnen', '[{"kategorie": "hist.", "text": "barocker Brunnen in Wien, der sich auf dem [[Hohen]] Markt im 1. Wiener Gemeindebezirk ([[Innere]] Stadt) befindet, auch bekannt als [[Josefsbrunnen]]"}, {"kategorie": "", "text": "Der Brunnen ist ein bedeutendes Kunstwerk des Wiener Barocks und ein zentraler Punkt auf einem der ältesten Plätze der Stadt"}, {"kategorie": "", "text": "Der Vermählungsbrunnen wurde zwischen 1729 und 1732 unter der Leitung des Architekten Joseph Emanuel Fischer von Erlach errichtet, dem Sohn des berühmten Architekten Johann Bernhard Fischer von Erlach. Der Brunnen wurde im Auftrag von [[Kaiser]] Karl VI. errichtet, um die Bedeutung des Hohen Markts als zentralen Platz der Stadt zu unterstreichen"}, {"kategorie": "", "text": "Der Brunnen zeigt eine Darstellung der Vermählung von Maria und Josef, einer wichtigen Szene aus der christlichen Ikonografie. Diese Darstellung soll die göttliche Ordnung und den Segen der Ehe symbolisieren und war für die religiös geprägte Gesellschaft der damaligen Zeit von großer Bedeutung."}]'::jsonb, ''),
  ('josefsbrunnan', 'Josefsbrunnan', '', '', '', '', 'Josefsbrunnen', '[{"kategorie": "hist.", "text": "barocker Brunnen in Wien, der sich auf dem [[Hohen]] Markt im 1. Wiener Gemeindebezirk ([[Innere]] Stadt) befindet, auch bekannt als [[Vermählungsbrunnen]]"}, {"kategorie": "", "text": "Der Brunnen ist ein bedeutendes Kunstwerk des Wiener Barocks und ein zentraler Punkt auf einem der ältesten Plätze der Stadt"}, {"kategorie": "", "text": "Der Josefsbrunnen wurde zwischen 1729 und 1732 unter der Leitung des Architekten Joseph Emanuel Fischer von Erlach errichtet, dem Sohn des berühmten Architekten Johann Bernhard Fischer von Erlach. Der Brunnen wurde im Auftrag von [[Kaiser]] Karl VI. errichtet, um die Bedeutung des Hohen Markts als zentralen Platz der Stadt zu unterstreichen"}, {"kategorie": "", "text": "Der Brunnen zeigt eine Darstellung der Vermählung von Maria und Josef, einer wichtigen Szene aus der christlichen Ikonografie. Diese Darstellung soll die göttliche Ordnung und den Segen der Ehe symbolisieren und war für die religiös geprägte Gesellschaft der damaligen Zeit von großer Bedeutung."}]'::jsonb, ''),
  ('wallnaschdrossn', 'Wallnaschdrossn', '', '', '', '', 'Wallnerstraße', '[{"kategorie": "hist.", "text": "historische Straße im 1. Wiener Gemeindebezirk ([[Innere]] Stadt)"}, {"kategorie": "", "text": "Sie verläuft in einem der ältesten Teile Wiens und ist bekannt für ihre architektonischen Sehenswürdigkeiten, darunter mehrere prächtige Palais und bedeutende historische Gebäude"}, {"kategorie": "", "text": "Der Name \"Wallnerstraße\" leitet sich von der Familie Wallner ab, die im Mittelalter hier ansässig war. Der Name hat sich über die Jahrhunderte erhalten und ist ein Zeugnis für die lange Geschichte der Straße"}, {"kategorie": "", "text": "Die Wallnerstraße ist ein wichtiger Teil des kulturellen und historischen Erbes Wiens. Sie spiegelt die architektonische Vielfalt und die lange Geschichte der Stadt wider und ist ein Beispiel dafür, wie Wien seine historische Bausubstanz pflegt und in das moderne Stadtleben integriert."}]'::jsonb, ''),
  ('braundschdaettn', 'Braundschdättn', '', '', '', '', 'Brandstätte', '[{"kategorie": "hist.", "text": "Straße im 1. Wiener Gemeindebezirk ([[Innere]] Stadt), die in der historischen Altstadt Wiens verläuft und Teil des engeren Stadtzentrums ist"}, {"kategorie": "", "text": "Die Straße verbindet den [[Stephansplatz]] mit dem [[Graben]], zwei der bekanntesten Plätze in Wien"}, {"kategorie": "", "text": "Der Name \"Brandstätte\" stammt aus der Zeit, als in diesem Gebiet Häuser nach einem verheerenden Brand zerstört wurden und die Fläche als \"Brandstätte\" bekannt wurde. Heute ist die Straße vor allem für ihre zentral gelegene Position und die Nähe zu wichtigen historischen und touristischen Attraktionen bekannt."}]'::jsonb, ''),
  ('schdubntoa', 'Schdubntoa', '', '', '', '', 'Stubentor', '[{"kategorie": "hist.", "text": "\"Stubentor\" (eines der historischen Stadttore Wiens, befand sich in der östlichen Stadtmauer, welche die [[Innere]] Stadt umschloss und an jener Stelle lag, wo heute der [[Stubenring]] beginnt)"}, {"kategorie": "hist.", "text": "Eingangstor  zur Stadt aus Richtung Osten (Das Stubentor wurde im Mittelalter errichtet und war eines der wichtigsten Tore der Wiener Stadtbefestigung. Es war Teil der ursprünglichen Stadtmauer, die im 13. Jahrhundert gebaut wurde, um Wien vor feindlichen Angriffen zu schützen. Das Stubentor ermöglichte den Zugang zur Stadt von Osten her und führte in die [[Stubenbastei]], einen Teil der Stadtbefestigung. Das Tor erhielt seinen Namen vermutlich aufgrund der Nähe zum [[Stubenviertel]], einem alten Stadtviertel, das für seine Handwerksbetriebe und Zünfte bekannt war. „Stube“ bezog sich ursprünglich auf Versammlungsräume, die von Zünften genutzt wurden. \nIm 19. Jahrhundert, als Wien seine mittelalterlichen Befestigungsanlagen aufgab und die Stadt modernisierte, wurde das Stubentor, wie die anderen Stadttore, abgerissen. Dieser Abriss fand im Zuge der Stadterweiterung und der Errichtung der [[Wiener]] Ringstraße statt, einem prestigeträchtigen Bauprojekt, das die mittelalterliche Stadtmauer durch eine prachtvolle Boulevardstraße ersetzte)"}]'::jsonb, ''),
  ('schottnviatl', 'Schottnviatl', '', '', '', '', 'Schottenviertel', '[{"kategorie": "hist.", "text": "\"historisches Stadtviertel im 1. Wiener Gemeindebezirk\" (Innere Stadt)"}, {"kategorie": "", "text": "eines der vier  Viertel des mittelalterlichen Wiens (neben dem [[Stubenviertel]], dem [[Kärntnerviertel]] und dem [[Widmerviertel]])"}, {"kategorie": "", "text": "Es befindet sich im nordwestlichen Teil der Altstadt und ist nach dem [[Schottenstift]] benannt"}]'::jsonb, ''),
  ('moelkabastei', 'Mölkabastei', '', '', '', '', 'Mölkerbastei', '[{"kategorie": "hist.", "text": "\"historischer Ort in Wien und einer der wenigen erhaltenen Überreste der alten Stadtbefestigung im 1. Wiener Gemeindebezirk\" ([[Innere]] Stadt)"}, {"kategorie": "", "text": "Sie befindet sich im Bereich des [[Schottenviertels]], nahe dem Wiener [[Schottenstift]] und der [[Universität]] Wien"}, {"kategorie": "", "text": "Die Mölkerbastei war ursprünglich Teil der Wiener Stadtmauer, die im 16. Jahrhundert im Zuge der Bedrohung durch das Osmanische Reich massiv ausgebaut wurde. Sie war eine von mehreren Basteien, die Wien umgaben und die Stadt vor Angriffen schützen sollten"}, {"kategorie": "", "text": "Während die meisten Teile der Wiener Stadtmauer im 19. Jahrhundert abgerissen wurden, um Platz für die Ringstraße zu schaffen, blieb die Mölkerbastei teilweise erhalten. Der Grund für den Erhalt war die enge Bebauung und die Integration der Bastei in die umliegenden Gebäude, was ihren Abriss verhinderte"}]'::jsonb, ''),
  ('universitaetsring', 'Universitätsring', '', '', '', '', 'Universitätsring', '[{"kategorie": "hist.", "text": "\"Teil der [[Wiener]] Ringstraße im 1. Wiener Gemeindebezirk\" ([[Innere]] Stadt), der vom [[Schwarzenbergplatz]] bis zum [[Schottentor]] führt und bis 2012 [[Dr-Karl-Lueger-Ring]] hieß (benannt nach dem ehemaligen Wiener Bürgermeister Karl Lueger [1844–1910], der als Begründer des modernen Wien gilt, da unter seiner Führung bedeutende Infrastrukturprojekte umgesetzt wurden, die Wien zu einer modernen Metropole machten)"}, {"kategorie": "", "text": "Am 7. Juli 2012 wurde der Dr.-Karl-Lueger-Ring in Universitätsring umbenannt. Diese Entscheidung wurde getroffen, um ein Zeichen gegen Antisemitismus und Rassismus zu setzen und die historische Verantwortung der Stadt Wien zu betonen (zumal Karl Lueger nicht nur als Bürgermeister von Wien Berühmtheit erlangte, sondern auch wegen seines offen zur Schau getragenen Antisemitismus)"}]'::jsonb, ''),
  ('schwoaznbeagplotz', 'Schwoaznbeagplotz', '', '', '', '', 'Schwarzenbergplatz', '[{"kategorie": "hist.", "text": "\"bedeutender Platz im 1. und 3. Wiener Gemeindebezirk\" ([[Innere]] Stadt bzw. [[Landstraße]])"}, {"kategorie": "", "text": "Er erstreckt sich südlich des Stadtzentrums und ist einer der größten und historisch bedeutendsten Plätze Wiens. Der Platz verbindet die [[Wiener]] Ringstraße mit der [[Prinz-Eugen-Straße]], die zum Schloss [[Belvedere]] führt"}, {"kategorie": "", "text": "Der Platz ist nach Karl Philipp Fürst zu [[Schwarzenberg]] (1771–1820) benannt, einem österreichischen Feldmarschall, der eine Schlüsselrolle in den [[Napoleonischen]] Kriegen spielte. Sein Sieg in der [[Schlacht]] bei Leipzig (1813) gilt als entscheidend für den Fall Napoleons. Zu seinen Ehren wurde in der Mitte des Platzes das [[Schwarzenbergdenkmal]] errichtet"}]'::jsonb, ''),
  ('schwoaznbeag', 'Schwoaznbeag', '', '', '', '', 'Schwarzenberg', '[{"kategorie": "", "text": "Er stammte aus dem einflussreichen Adelsgeschlecht der Schwarzenbergs und war eine zentrale Figur in den Befreiungskriegen, die zur Niederlage Napoleons und zur Neuordnung Europas führten"}, {"kategorie": "", "text": "Während der [[Koalitionskriege]] gegen das napoleonische Frankreich kämpfte Schwarzenberg in mehreren entscheidenden Schlachten. Er machte sich besonders im Fünften Koalitionskrieg (1809) einen Namen, in dem er an der Seite von [[Erzherzog]] Karl in der [[Schlacht]] bei Wagram kämpfte, die Österreich jedoch verlor. Trotz der Niederlage stieg Schwarzenberg aufgrund seiner strategischen Fähigkeiten in der Armee auf"}, {"kategorie": "", "text": "1813 wurde er zum Oberbefehlshaber der verbündeten Armeen von Österreich, Preußen, Russland und Schweden ernannt, die sich gegen [[Napoleon]] stellten"}, {"kategorie": "", "text": "Schwarzenbergs größter militärischer Erfolg war die [[Schlacht]] bei Leipzig, auch als [[Völkerschlacht]] bekannt. Diese Schlacht fand vom 16. bis 19. Oktober 1813 statt und gilt als die größte und entscheidendste Schlacht der [[Napoleonischen]] Kriege. Unter Schwarzenbergs Führung siegten die verbündeten Mächte, was zu einem Wendepunkt im Kampf gegen Napoleon führte. Nach dieser Niederlage musste Napoleon seine Truppen aus Deutschland zurückziehen"}, {"kategorie": "", "text": "Nach den [[Befreiungskriegen]] zog sich Schwarzenberg aus dem aktiven Militärdienst zurück. Er starb 1820 in Leipzig, wo er einige Jahre zuvor seinen größten Sieg errungen hatte."}]'::jsonb, ''),
  ('schwoaznbeagdenkmoi', 'Schwoaznbeagdenkmoi', '', '', '', '', 'Schwarzenbergdenkmal', '[{"kategorie": "allg.", "text": "\"Reiterstandbild zu Ehren von Karl Philipp Fürst zu [[Schwarzenberg]], einem bedeutenden österreichischen Feldmarschall und Sieger in der [[Schlacht]] bei Leipzig (1813) während der [[Napoleonischen]] Kriege\""}, {"kategorie": "", "text": "Das Denkmal steht zentral auf dem [[Schwarzenbergplatz]], einem wichtigen Verkehrsknotenpunkt in Wien, der nach Fürst Schwarzenberg benannt wurde. Es bildet einen der markanten Punkte in der Stadt und befindet sich in der Nähe des [[Hochstrahlbrunnens]]"}, {"kategorie": "", "text": "Das Reiterstandbild wurde von dem Bildhauer Ernst Julius Hähnel entworfen und zeigt Karl Philipp Fürst zu Schwarzenberg in militärischer Uniform hoch zu Ross. Die Statue symbolisiert ihn als siegreichen Feldherrn und Führer der Alliierten in der Schlacht bei Leipzig"}, {"kategorie": "", "text": "Das Denkmal wurde 1867 enthüllt und ist ein Ausdruck des österreichischen Stolzes auf Schwarzenbergs militärische Erfolge und seine Rolle bei der Befreiung Europas von der napoleonischen Herrschaft."}]'::jsonb, ''),
  ('hochschdroibrunnan', 'Hochschdroibrunnan', '', '', '', '', 'Hochstrahlbrunnen', '[{"kategorie": "hist.", "text": "\"monumentaler Brunnen, der 1873 zur Feier der Eröffnung der ersten [[Wiener]] Hochquellwasserleitung errichtet wurde\""}, {"kategorie": "", "text": "Er bildet das zentrale Element des [[Schwarzenbergplatzes]] und ist nicht nur ein technisches Denkmal, sondern auch ein beliebter Treffpunkt sowie ein markantes Wahrzeichen des Platzes"}]'::jsonb, ''),
  ('pasqualatihaus', 'Pasqualatihaus', '', '', '', '', 'Pasqualatihaus', '[{"kategorie": "hist.", "text": "\"historisches Gebäude im 1. Wiener Gemeindebezirk\" ([[Innere]] Stadt)"}, {"kategorie": "", "text": "Es befindet sich auf der [[Mölkerbastei]], einer erhaltenen Bastion der ehemaligen Wiener Stadtmauer, nahe der [[Universität]] Wien"}, {"kategorie": "", "text": "Ludwig van Beethoven lebte in diesem Haus in verschiedenen Perioden zwischen 1804 und 1815, einer Zeit, in der er einige seiner bedeutendsten Werke komponierte. Dazu gehören Teile seiner 4. bis 8. Symphonie, die Oper \"Fidelio\" sowie zahlreiche Klavier- und Kammermusikwerke"}, {"kategorie": "", "text": "Das Pasqualatihaus ist ein typisches Beispiel für die Wohnarchitektur des 18. Jahrhunderts in Wien. Das vierstöckige Gebäude hat eine schlichte Fassade, die zum Teil die nüchterne Eleganz der damaligen Zeit widerspiegelt. Heute ist dieser Teil des Hauses als Museum eingerichtet, das Beethovens Leben und Werk gewidmet ist."}]'::jsonb, ''),
  ('dominikanabastei', 'Dominikanabastei', '', '', '', '', 'Dominikanerbastei', '[{"kategorie": "hist.", "text": "\"historischer Bereich im 1. Wiener Gemeindebezirk\" ([[Innere]] Stadt)"}, {"kategorie": "", "text": "Sie war Teil der ehemaligen Wiener Stadtbefestigung und liegt im südöstlichen Teil der Altstadt, im Bereich des sogenannten [[Stubenviertels]]"}, {"kategorie": "", "text": "Der Name \"Dominikanerbastei\" leitet sich vom nahegelegenen [[Dominikanerkloster]] und der [[Dominikanerkirche]] ab, die sich in unmittelbarer Nähe befinden"}, {"kategorie": "", "text": "Die Dominikanerbastei war eine von mehreren Basteien, die im 16. Jahrhundert als Teil der Stadtbefestigung von Wien errichtet wurden. Diese Basteien waren notwendig, um die Stadt vor Angriffen, insbesondere während der Türkenbelagerungen, zu schützen. Die Dominikanerbastei lag an der südöstlichen Ecke der Stadtmauer"}, {"kategorie": "Straßenname", "text": "Heute ist die Dominikanerbastei der Name einer Straße, die entlang des ehemaligen Verlaufs der Stadtmauer verläuft. Die Straße verbindet das Stubenviertel mit anderen Teilen der Inneren Stadt und ist ein Teil des historischen Stadtgefüges"}]'::jsonb, ''),
  ('dominikaanakloosta', 'Dominikaanakloosta', '', '', '', '', 'Dominikanerkloster', '[{"kategorie": "hist.", "text": "\"bedeutendes religiöses und historisches Kloster im 1. Wiener Gemeindebezirk\" ([[Innere]] Stadt)"}, {"kategorie": "", "text": "Es gehört zum Dominikanerorden und befindet sich in der Nähe der [[Dominikanerbastei]] im [[Stubenviertel]] (einem der vier historischen Stadtviertel des 1. Wiener Gemeindebezirks)"}, {"kategorie": "", "text": "Das Dominikanerkloster in Wien wurde im Jahr 1226 gegründet, nachdem der Dominikanerorden, der 1215 vom heiligen Dominikus gegründet worden war, sich in Wien niedergelassen hatte. Es ist eines der ältesten Klöster Wiens und spielte eine wichtige Rolle im religiösen und geistlichen Leben der Stadt"}]'::jsonb, ''),
  ('dominikaanakiachn', 'Dominikaanakiachn', '', '', '', '', 'Dominikanerkirche', '[{"kategorie": "hist.", "text": "\"bedeutende barocke Kirche im 1. Wiener Gemeindebezirk\" ([[Innere]] Stadt), auch bekannt als \"Kirche Maria Rotunda\""}, {"kategorie": "", "text": "Sie gehört zum [[Dominikanerkloster]] und befindet sich im [[Stubenviertel]] nahe der [[Dominikanerbastei]]"}, {"kategorie": "", "text": "Die Dominikanerkirche wurde im 17. Jahrhundert errichtet, nachdem der ursprüngliche gotische Kirchenbau, der ab 1237 bestand, durch die Türkenbelagerung beschädigt wurde"}, {"kategorie": "", "text": "Die Kirche ist ein beeindruckendes Beispiel für den italienisch beeinflussten Barockstil in Wien mit Fresken, die Szenen aus dem Leben der Heiligen Dominikus und Maria darstellen, sowie zahlreichen Altären und Statuen"}, {"kategorie": "", "text": "Die Kuppel der Kirche ist ein weiteres architektonisches Highlight. Sie ist reich verziert und vermittelt dem Betrachter einen Eindruck von Höhe und Weite, wie es typisch für den Barockstil ist"}]'::jsonb, ''),
  ('tuchlaubn', 'Tuchlaubn', '', '', '', '', 'Tuchlauben', '[{"kategorie": "hist.", "text": "\"historische Straße im 1. Wiener Gemeindebezirk\" ([[Innere]] Stadt)"}, {"kategorie": "", "text": "Sie gehört zu den ältesten Straßen Wiens und verläuft durch das sogenannte [[Widmerviertel]], eines der vier mittelalterlichen Stadtviertel der Wiener Altstadt"}, {"kategorie": "", "text": "Der Name \"Tuchlauben\" leitet sich von den Tuchhändlern ab, die im Mittelalter in dieser Straße ansässig waren. \"Lauben\" bezieht sich auf die Arkadengänge oder offenen Verkaufshallen, unter denen die Händler ihre Waren anboten. Die Tuchlauben war daher ein Zentrum des Tuchhandels und anderer Handelsaktivitäten im mittelalterlichen Wien"}]'::jsonb, ''),
  ('noglagossn', 'Noglagossn', '', '', '', '', 'Naglergasse', '[{"kategorie": "hist.", "text": "\"historische Gasse im 1. Wiener Gemeindebezirk\" ([[Innere]] Stadt)"}, {"kategorie": "", "text": "Die Naglergasse hat ihren Namen von den Naglern und Handwerkern, die Nägel und ähnliche Metallwaren herstellten. Im Mittelalter und in der frühen Neuzeit war die Gasse ein Zentrum dieses Handwerks, und viele der dort ansässigen Handwerksbetriebe gehörten dieser Zunft an"}, {"kategorie": "", "text": "Die Naglergasse zeichnet sich durch ihre gut erhaltene historische Bausubstanz aus. Viele Gebäude in der Gasse stammen aus dem 17. und 18. Jahrhundert und spiegeln die Architektur dieser Zeit wider. Die Gasse ist relativ schmal, was ihr einen besonderen, fast dörflichen Charme verleiht, obwohl sie sich mitten in der Großstadt befindet"}]'::jsonb, ''),
  ('peedaskiachn', 'Peedaskiachn', '', '', '', '', 'Peterskirche', '[{"kategorie": "wörtlich", "text": "\"bedeutende, barocke, römisch-katholische Kirche im 1. Wiener Gemeindebezirk\" ([[Innere]] Stadt), auch bekannt als \"Kirche St. Peter\""}, {"kategorie": "", "text": "Sie befindet sich nahe dem [[Graben]] und ist eines der markantesten Beispiele barocker [[Sakralarchitektur]] in Wien"}, {"kategorie": "", "text": "Die Peterskirche ist ein herausragendes Beispiel des Hochbarock in Wien. Sie zeichnet sich durch ihre zentrale Kuppel aus, die dem Innenraum eine besondere Weite und Höhe verleiht. Die Fassade der Kirche ist reich verziert mit Säulen, Statuen und barocken Ornamenten. Besonders bemerkenswert sind die Fresken in der Kuppel, die Szenen aus dem Leben des Heiligen Petrus darstellen."}]'::jsonb, ''),
  ('peedasplotz', 'Peedasplotz', '', '', '', '', 'Petersplatz', '[{"kategorie": "allg.", "text": "\"historischer Platz im 1. Wiener Gemeindebezirk ([[Innere]] Stadt), der rund um die [[Peterskirche]] liegt\""}, {"kategorie": "", "text": "Dieser Platz hat eine lange Geschichte, die bis ins Mittelalter zurückreicht und eng mit der Entwicklung des Sakralbereichs um die Peterskirche und des ehemaligen Friedhofs, dem sogenannten Petersfreithof, verbunden ist"}, {"kategorie": "", "text": "Der Platz selbst wurde 1786 erstmals als Petersplatz erwähnt und diente zeitweise auch Marktzwecken, bevor er seine heutige Funktion als Kirchenplatz erhielt"}, {"kategorie": "", "text": "Am Petersplatz standen ursprünglich mehrere kleine Häuser, darunter das sogenannte Eisgrübel (später als Im Eisgrübel bekannt), ein kleiner Gässchenbereich, der erst 1895 verschwand. In der Mitte der Häusergruppe wurde 1701 ein freistehendes Gebäude als Sitz der Polizei-Hauptwache errichtet, das bis 1845 nachgewiesen ist"}, {"kategorie": "", "text": "Ebenfalls war ab dem 17. Jahrhundert ein Wachlokal der [[Stadtguardia]] an die Nordseite der Peterskirche angebaut, das jedoch beim Bau der barocken Peterskirche entfernt wurde"}, {"kategorie": "", "text": "Die [[Peterskirche]], die den Platz dominiert, wurde 1724 fertiggestellt und ist ein Meisterwerk der Barockarchitektur in Wien. Sie steht im Mittelpunkt des Petersplatzes und verleiht ihm seine besondere kulturelle und historische Bedeutung"}, {"kategorie": "", "text": "Der Petersplatz in Wien ist sohin ein historischer Ort, der eng mit der Peterskirche und dem ehemaligen Petersfreithof verbunden ist. Über die Jahrhunderte hat sich der Platz von einem Friedhof und Marktplatz zu einem architektonisch wichtigen und kulturell bedeutenden Teil der Wiener Innenstadt entwickelt."}]'::jsonb, ''),
  ('schdubnviatl', 'Schdubnviatl', '', '', '', '', 'Stubenviertel', '[{"kategorie": "hist.", "text": "\"historisches Stadtviertel im 1. Wiener Gemeindebezirk\" ([[Innere]] Stadt)"}, {"kategorie": "", "text": "eines der vier  Viertel des mittelalterlichen Wiens (neben dem [[Kärntnerviertel]], dem [[Widmerviertel]] und dem [[Schottenviertel]])"}, {"kategorie": "", "text": "Es befindet sich im östlichen Teil der Altstadt und ist eines der ältesten Viertel Wiens. Das Stubenviertel ist nach der [[Stubenbastei]] benannt, einer ehemaligen Bastion der Wiener Stadtmauer, die sich in diesem Bereich befand. Die Stadtmauer wurde im 19. Jahrhundert abgerissen, aber der Name blieb erhalten (die Bezeichnung „Stube“ bezog sich ursprünglich auf Versammlungsräume, die von Zünften genutzt wurden)"}, {"kategorie": "", "text": "Das Viertel ist geprägt von engen, verwinkelten Gassen, historischen Gebäuden und Plätzen, die einen besonderen Charme und eine lange Geschichte ausstrahlen. Bekannte Straßen und Plätze im Stubenviertel sind unter anderem die [[Wollzeile]], die [[Bäckerstraße]] und der [[Fleischmarkt]]"}, {"kategorie": "", "text": "Es wurde durch die Jesuiten zum Zentrum des studentischen Lebens (alte Universität Wien). Heute besticht es unter anderem durch die neu renovierte [[Akademie]] der Wissenschaften mit dem wunderbar gestalteten Festsaal, dem [[Jesuitenkloster]], dem barocken [[Heiligenkreuzerhof]] und der Gegend rund um die [[Griechengasse]]"}]'::jsonb, ''),
  ('heilignkreizahof', 'Heilignkreizahof', '', '', '', '', 'Heiligenkreuzerhof', '[{"kategorie": "hist.", "text": "\"historischer Gebäudekomplex im 1. Wiener Gemeindebezirk\" ([[Innere]] Stadt)"}, {"kategorie": "", "text": "Er gehört zu den ältesten und bedeutendsten Klosterhöfen in Wien und steht in enger Verbindung mit dem Zisterzienserstift Heiligenkreuz im [[Wienerwald]]"}, {"kategorie": "", "text": "Der Heiligenkreuzer Hof wurde im 12. Jahrhundert gegründet, als das Zisterzienserstift Heiligenkreuz in Wien einen Stadtstützpunkt errichtete. Das Stift Heiligenkreuz selbst wurde 1133 gegründet und ist eines der ältesten Zisterzienserklöster der Welt, das bis heute in Betrieb ist"}, {"kategorie": "", "text": "Der Heiligenkreuzer Hof ist ein denkmalgeschütztes Bauwerk und zählt zu den wertvollsten historischen Gebäuden Wiens. Er ist ein bedeutendes Zeugnis der klösterlichen Architektur und Geschichte der Stadt."}]'::jsonb, ''),
  ('baeckaschdrossn', 'Bäckaschdrossn', '', '', '', '', 'Bäckerstraße', '[{"kategorie": "hist.", "text": "\"historische Straße im 1. Wiener Gemeindebezirk\" ([[Innere]] Stadt)"}, {"kategorie": "", "text": "Sie befindet sich im [[Stubenviertel]], einem der vier alten Stadtviertel Wiens, und verbindet die [[Wollzeile]] mit dem [[Lugeck]]"}, {"kategorie": "", "text": "Die Bäckerstraße erhielt ihren Namen im Mittelalter, da sich in dieser Straße zahlreiche Bäckereien befanden. Diese Straße war das Zentrum des Bäckerhandwerks in Wien, und viele der hier ansässigen Betriebe belieferten die Stadt mit Brot und anderen Backwaren"}, {"kategorie": "", "text": "Im Laufe der Jahrhunderte hat sich die Bäckerstraße von einer reinen Handwerksstraße zu einer Wohn- und Geschäftsstraße entwickelt. Viele der historischen Gebäude entlang der Straße zeugen noch heute von der reichen Vergangenheit des Viertels"}]'::jsonb, ''),
  ('schbiiglgossn', 'Schbiiglgossn', '', '', '', '', 'Spiegelgasse', '[{"kategorie": "hist.", "text": "historische Straße im 1. Wiener Gemeindebezirk ([[Innere]] Stadt), in unmittelbarer Nähe von [[Graben]], [[Kohlmarkt]] und [[Dorotheergasse]]"}, {"kategorie": "", "text": "Die Spiegelgasse ist Teil des historischen Zentrums von Wien, das zum UNESCO-Weltkulturerbe gehört"}, {"kategorie": "", "text": "In der Spiegelgasse 12 lebte Wolfgang Amadeus Mozart für kurze Zeit im Jahr 1781. Dieses Gebäude, auch bekannt als \"Mozarthaus\", ist eines der vielen Orte in Wien, die mit dem Leben des Komponisten verbunden sind."}]'::jsonb, ''),
  ('doroteagossn', 'Doroteagossn', '', '', '', '', 'Dorotheergasse', '[{"kategorie": "hist.", "text": "Straße im 1. Wiener Gemeindebezirk ([[Innere]] Stadt) in unmittelbarer Nähe von [[Stephansplatz]], [[Graben]] und vieler wichtiger Sehenswürdigkeiten der Wiener Altstadt"}, {"kategorie": "", "text": "Die Dorotheergasse ist vor allem durch das \"Dorotheum\" bekannt, eines der ältesten und größten Auktionshäuser der Welt. Es wurde 1707 gegründet und hat seinen Namen von der Dorotheerkirche, die ursprünglich an dieser Stelle stand."}]'::jsonb, ''),
  ('braeunaschdrossn', 'Bräunaschdrossn', '', '', '', '', 'Bräunerstraße', '[{"kategorie": "hist.", "text": "historische Straße im 1. Wiener Gemeindebezirk ([[Innere]] Stadt)"}, {"kategorie": "", "text": "Sie verläuft von der [[Habsburgergasse]] bis zum [[Graben]] und befindet sich in der Nähe des [[Kohlmarkts]] und des [[Michaelerplatzes]]"}, {"kategorie": "", "text": "Die Bräunerstraße ist Teil des historischen Zentrums von Wien und gesäumt von historischen Gebäuden, die verschiedene architektonische Stile repräsentieren. Viele der Gebäude stammen aus dem 17. und 18. Jahrhundert und sind gut erhalten, was der Straße ein charakteristisches und elegantes Erscheinungsbild verleiht"}, {"kategorie": "", "text": "Die Bräunerstraße in Wien ist nach der Familie Bräuner benannt, einer wohlhabenden und einflussreichen Familie, die im 17. Jahrhundert in Wien lebte. Insbesondere wird die Straße mit dem Namen von Johann Michael Bräuner (auch Breuner geschrieben) in Verbindung gebracht, der ein reicher Wiener Bürger und Gastwirt war"}, {"kategorie": "", "text": "Johann Michael Bräuner betrieb im 17. Jahrhundert das \"Braune Haus\" (daher der Name Bräuner), das an der Stelle stand, wo heute die Bräunerstraße verläuft. Das Haus war ein bekanntes Wirtshaus und eine beliebte Einkehr für Reisende und Einheimische. Aufgrund des Erfolgs und der Bedeutung des Hauses und seiner Betreiberfamilie wurde die Straße nach ihnen benannt."}]'::jsonb, ''),
  ('plaunkngossn', 'Plaunkngossn', '', '', '', '', 'Plankengasse', '[{"kategorie": "hist.", "text": "kurze, aber historisch bedeutende Straße im 1. Wiener Gemeindebezirk ([[Innere]] Stadt), die in der Nähe des [[Kohlmarkts]] verläuft"}, {"kategorie": "", "text": "Die Plankengasse hat ihren Namen von den \"Planken\", die ursprünglich dazu dienten, den sumpfigen Untergrund der Gegend zu überbrücken. Die Gegend war in früheren Zeiten von Wasserläufen und Sümpfen durchzogen, weshalb solche Holzplanken notwendig waren, um den Bereich begehbar zu machen"}, {"kategorie": "", "text": "Die Plankengasse liegt im Herzen der Wiener Altstadt, in unmittelbarer Nähe zu bedeutenden Sehenswürdigkeiten wie dem [[Michaelerplatz]] und der [[Hofburg]]. Dies macht sie zu einem Teil des UNESCO-Weltkulturerbes \"Historisches Zentrum von Wien\""}]'::jsonb, ''),
  ('lugeck', 'Lugeck', '', '', '', '', 'Lugeck', '[{"kategorie": "hist.", "text": "\"historischer Platz im 1. Wiener Gemeindebezirk\" ([[Innere]] Stadt)"}, {"kategorie": "", "text": "Er gehört zum [[Stubenviertel]] und befindet sich in unmittelbarer Nähe zur [[Rotenturmstraße]] und ist ein bedeutender Teil des alten Stadtzentrums von Wien"}, {"kategorie": "", "text": "Der Name \"Lugeck\" leitet sich von dem mittelhochdeutschen Wort \"lugen\" ab, was so viel wie \"schauen\" oder \"spähen\" bedeutet. Historisch gesehen könnte der Platz seinen Namen aufgrund seiner Lage erhalten haben, die eine gute Aussicht auf das umliegende Gebiet ermöglichte"}, {"kategorie": "", "text": "Heute ist das Lugeck ein beliebter Treffpunkt in der Wiener Innenstadt. Es ist von Restaurants, Cafés und Geschäften umgeben, die sowohl Einheimische als auch Touristen anziehen"}]'::jsonb, ''),
  ('wollzeile', 'Wollzeile', '', '', '', '', 'Wollzeile', '[{"kategorie": "hist.", "text": "historische und bedeutende Straße im 1. Wiener Gemeindebezirk ([[Innere]] Stadt)"}, {"kategorie": "", "text": "Sie verläuft durch das [[Stubenviertel]] und erstreckt sich von der [[Rotenturmstraße]] bis zum [[Dr]].-Karl-Lueger-Platz"}, {"kategorie": "", "text": "Der Name \"Wollzeile\" stammt aus dem Mittelalter, als die Straße ein Zentrum des Handels mit Wolle und Textilien war. Händler und Handwerker, die mit Wolle arbeiteten, hatten hier ihre Geschäfte und Werkstätten, was der Straße ihren Namen gab"}, {"kategorie": "", "text": "Die Wollzeile ist geprägt von einer Mischung aus historischen und modernen Gebäuden. Einige Häuser entlang der Straße stammen aus der Barockzeit, während andere aus dem 19. und frühen 20. Jahrhundert stammen. Im Laufe der Jahrhunderte entwickelte sich die Wollzeile von einem Handelszentrum für Textilien zu einer lebendigen Einkaufs- und Geschäftsstraße"}]'::jsonb, ''),
  ('rotntuamschdrossn', 'Rotntuamschdrossn', '', '', '', '', 'Rotenturmstraße', '[{"kategorie": "hist.", "text": "\"bedeutende Straße im 1. Wiener Gemeindebezirk\" ([[Innere]] Stadt)"}, {"kategorie": "", "text": "Sie verläuft durch das [[Stubenviertel]] und verbindet den [[Stephansplatz]], das Herz der Wiener Innenstadt, mit dem [[Schwedenplatz]] am [[Donaukanal]]"}, {"kategorie": "", "text": "Die Rotenturmstraße verdankt ihren Namen dem \"Roten Turm\", einem Wehrturm, der im Mittelalter Teil der Wiener Stadtbefestigung war. Der Turm selbst existiert heute nicht mehr, aber sein Name blieb in der Straßenbezeichnung erhalten"}, {"kategorie": "", "text": "Heute ist die Rotenturmstraße eine belebte Einkaufsstraße, die zahlreiche Geschäfte, Boutiquen, Restaurants und Cafés beherbergt."}]'::jsonb, '')
